using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplication? _app;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var chatClient = _app!.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        // Evaluate the response for relevance and coherence
        await scenario.EvaluateAsync(
            messages,
            response,
            [new RelevanceEvaluator(), new CoherenceEvaluator()]);

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Response should not be empty.");
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUp()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesFollowUp));

        var chatClient = _app!.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about machine learning in one sentence."),
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.AddRange(response.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "Can you give an example?"));

        var followUpResponse = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(
            messages,
            followUpResponse,
            [new RelevanceEvaluator(), new CoherenceEvaluator()]);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(followUpResponse.Text),
            "Follow-up response should not be empty.");
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }
}

